INSERT INTO `startup_profiles` (`id`, `user_id`, `company_name`, `registration_number`, `dpiit_recognized`, `dpiit_number`, `sector`, `stage`, `founded_year`, `team_size`, `annual_turnover`, `location_state`, `location_city`, `website`, `description`, `primary_skills`, `certifications`, `past_experience`, `verified_status`, `profile_completeness_pct`) VALUES
(1, 4, 'AeroTech Defence Labs Pvt Ltd', 'U72900KA2021PTC145001', 1, 'DIPP98214', 'Defence & Aerospace', 'GROWTH', 2021, 24, 45000000.00, 'Karnataka', 'Bengaluru', 'https://aerotechdefence.demo', 'Specializing in autonomous high-altitude UAV systems, edge AI computer vision, and rugged tactical drone hardware.', '["Edge AI", "Computer Vision", "UAV Hardware", "Tactical Robotics", "Embedded Linux", "C++", "ROS2"]', '["ISO 9001:2015", "AS9100D Aerospace", "CEMILAC Approved Design"]', 'Delivered 12 tactical perimeter surveillance units to Border Security forces in 2023 under pilot evaluation.', 'VERIFIED', 95),
(2, 5, 'MedPulse HealthTech Solutions', 'U85100MH2020PTC334102', 1, 'DIPP87231', 'Healthcare & Life Sciences', 'GROWTH', 2020, 18, 28000000.00, 'Maharashtra', 'Pune', 'https://medpulse.demo', 'Pioneering portable point-of-care vital diagnostic kiosks and cloud-connected remote health monitoring kits for rural PHCs.', '["Medical Device Hardware", "IoT Telemetry", "HIPAA/EHR Integration", "Embedded C", "Python", "React Native"]', '["CDSCO Class B Approved", "ISO 13485:2016", "CE Mark"]', 'Deployed 85 telemedicine booths across 3 district hospitals in Maharashtra under CSR initiatives.', 'VERIFIED', 90),
(3, 6, 'GreenGrid Energy Systems', 'U40100DL2022PTC412003', 1, 'DIPP11452', 'Renewable Energy & Cleantech', 'EARLY', 2022, 12, 15000000.00, 'Delhi', 'New Delhi', 'https://greengrid.demo', 'AI-driven microgrid orchestration, distributed energy storage systems, and solar power predictive dispatch controllers.', '["Power Electronics", "Microgrid Optimization", "Time Series Forecasting", "Python", "MQTT", "SCADA Integration"]', '["ISO 14001:2015", "BIS Certified Inverter Controller"]', 'Piloted 4 community solar microgrid controllers in Ladakh and Himachal Pradesh.', 'VERIFIED', 85),
(4, 7, 'KisanAgri AI & Drone Robotics', 'U01100GJ2021PTC215004', 1, 'DIPP93450', 'AgriTech & Rural Tech', 'GROWTH', 2021, 15, 22000000.00, 'Gujarat', 'Ahmedabad', 'https://kisanagri.demo', 'Autonomous multispectral drone imagery for early crop disease detection, soil moisture mapping, and variable rate spray guidance.', '["Multispectral Imaging", "GIS & Remote Sensing", "Autonomous Flight Control", "Deep Learning", "TensorFlow"]', '["DGCA Type Certified Drone", "ISO 9001:2015"]', 'Mapped over 50,000 hectares for State Seed Corporation crop insurance yield estimation.', 'VERIFIED', 88),
(5, 8, 'CyberShield DefTech Innovations', 'U72200HR2022PTC518005', 1, 'DIPP10842', 'Cyber Security & Defence', 'EARLY', 2022, 14, 18500000.00, 'Haryana', 'Gurugram', 'https://cybershield.demo', 'Next-generation zero-trust network access, AI automated threat hunting, and sovereign Linux kernel security hardening.', '["Zero Trust Network Access", "Kernel eBPF", "Network Intrusion Detection", "Rust", "Go", "Kubernetes Security"]', '["CERT-In Empanelled Partner Ready", "ISO 27001:2022"]', 'Completed red team vulnerability assessments for 2 municipal smart city command centres.', 'VERIFIED', 82)
INSERT INTO `tenders` (`id`, `reference_number`, `title`, `description`, `department_id`, `category_id`, `budget_inr`, `publication_date`, `deadline`, `eligibility_criteria`, `required_skills`, `required_documents`, `evaluation_criteria`, `status`, `source_url`, `created_by_officer_id`, `is_demo`) VALUES
(1, 'DRDO/2026/AI-SURV-001', 'AI-Powered Threat Detection & Edge Surveillance System', 'Procurement of ruggedized edge computing devices running deep learning neural networks for perimeter threat detection, vehicle license plate recognition, and intruder tracking in harsh environmental conditions (-20°C to +55°C).', 1, 1, 45000000.00, '2026-09-01', '2026-11-30 17:00:00', 'Startups registered with DPIIT. Minimum 1 year operational experience in edge AI / computer vision. Team must have demonstrated prior defense or security prototype testing. Turn-over exemption granted for recognized startups.', 'Edge AI, Computer Vision, ROS2, Embedded Linux, Tactical Robotics, C++', 'DPIIT Recognition Certificate, Incorporation Certificate, Technical Architecture Proposal, CEMILAC/MIL-STD test certificates, Past Performance Testimonials', 'Technical Feasibility (40%), Rugged Hardware Readiness (25%), Security Compliance (20%), Commercial Pricing (15%)', 'PUBLISHED', 'https://drdo.gov.in/tenders/2026/ai-surv', 2, 1),
INSERT INTO `applications` (`id`, `application_number`, `tender_id`, `startup_id`, `status`, `proposal_summary`, `proposed_cost_inr`, `technical_score`, `financial_score`, `officer_notes`, `clarification_note`, `submitted_at`, `is_demo`) VALUES
(1, 'APP-2026-001-AER', 1, 1, 'UNDER_REVIEW', 'AeroTech proposes a customized FalconEye Edge AI pod equipped with NVIDIA Jetson Orin Industrial module, rated -40C to +85C with MIL-STD-810H vibration resistance.', 42500000.00, 92.50, NULL, 'Preliminary technical proposal demonstrates strong alignment with DRDO perimeter specifications. Awaiting lab environmental chamber test records.', NULL, '2026-09-28 11:30:00', 1),
