INSERT INTO `tender_matches` (`id`, `startup_id`, `tender_id`, `relevance_score`, `matched_skills`, `missing_requirements`, `explanation`, `preliminary_status`, `calculated_at`) VALUES
(1, 1, 1, 94.50, '["Edge AI", "Computer Vision", "ROS2", "Embedded Linux", "Tactical Robotics"]', '["MIL-STD-810H Chamber Chamber Third-Party Lab Certificate"]', 'AeroTech demonstrates an exceptional 94.5% match with DRDO AI Edge Surveillance tender. Sector alignment is 100%, and 5 out of 6 required technical competencies are fully documented in verified company profile.', 'HIGHLY_RELEVANT', '2026-10-01 08:30:00'),
(2, 1, 12, 91.00, '["UAV Hardware", "Embedded Linux", "Autonomous Flight Control"]', '["High-Altitude Test Chamber Telemetry Above 16,000 ft"]', 'Strong alignment in autonomous UAV platforms. Startup has delivered low-altitude surveillance pods; needs altitude chamber telemetry validation.', 'HIGHLY_RELEVANT', '2026-10-01 08:35:00'),
(3, 2, 2, 96.00, '["Medical Device Hardware", "IoT Telemetry", "HIPAA/EHR Integration", "Embedded C"]', '["Cold-Chain Reagent Logistics Partner SLA"]', 'Outstanding match for Rural Health Kiosk. Startup possesses verified CDSCO Class B certification, ISO 13485 quality systems, and prior deployment of 85 units.', 'HIGHLY_RELEVANT', '2026-10-01 09:00:00'),
(4, 3, 3, 89.00, '["Power Electronics", "Microgrid Optimization", "Time Series Forecasting", "SCADA Integration"]', '["100 kWh Field Battery Warranty Certificate"]', 'High technical match for Himalayan microgrid management. Past deployments in Ladakh give strong geographical domain evidence.', 'HIGHLY_RELEVANT', '2026-10-01 09:15:00'),
(5, 4, 4, 95.00, '["Multispectral Imaging", "GIS & Remote Sensing", "Autonomous Flight Control", "Deep Learning"]', '["Additional 5 Drone Pilot RPTO License Copies"]', 'Near-perfect match for ICAR agricultural drone mapping tender. Verified DGCA Type Certificate and extensive 50k hectare past experience.', 'HIGHLY_RELEVANT', '2026-10-01 09:30:00')
